-- Server-backed Life sinking funds for the iOS Life pillar.
-- client_id preserves the offline UUID generated by the app so bulk syncs are
-- idempotent across retries and iCloud restores.

CREATE TABLE IF NOT EXISTS sinking_funds (
  id                 SERIAL PRIMARY KEY,
  user_id            UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  client_id          UUID NOT NULL,
  name               VARCHAR(200) NOT NULL,
  target_amount      NUMERIC(12,2) NOT NULL DEFAULT 0,
  saved_amount       NUMERIC(12,2) NOT NULL DEFAULT 0,
  target_date        DATE,
  paycheck_interval  VARCHAR(20) NOT NULL DEFAULT 'biweekly'
    CHECK (paycheck_interval IN ('weekly', 'biweekly', 'monthly')),
  icon               VARCHAR(80) NOT NULL DEFAULT 'banknote.fill',
  color              VARCHAR(80) NOT NULL DEFAULT 'pillarSinking',
  created_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(user_id, client_id)
);

CREATE INDEX IF NOT EXISTS idx_sinking_funds_user_target
  ON sinking_funds(user_id, target_date);

